const el=id=>document.getElementById(id),n=v=>new Intl.NumberFormat('ru-RU',{maximumFractionDigits:2}).format(Number(v)||0),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));let selected=null,data=null,stores=[];async function api(url,body){const r=await fetch(url,body?{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body)}:{}),v=await r.json();if(!r.ok)throw Error(v.error);return v}async function refresh(){try{stores=await api('/api/stores');if(!selected&&stores.length)selected=stores[0].id;el('shops').innerHTML=stores.map(s=>`<button data-store="${s.id}" class="${selected===s.id?'active':''}">${esc(s.name)} · ${s.job?.status==='running'?'Загружается':s.job?.status==='partial'?'Загружено частично':s.updatedAt?'Данные загружены':'Подключён'}</button>`).join('');if(!selected)return;const s=stores.find(s=>s.id===selected);el('real').hidden=false;el('real-title').textContent=s.name;el('sync').disabled=s.job?.status==='running';el('status').textContent=(s.job?s.job.stage+' · обработано записей: '+s.job.count:'Подключено')+(s.updatedAt?'\nПоследнее обновление: '+new Date(s.updatedAt).toLocaleString('ru-RU'):'')+(s.job?.errors?.length?'\n'+s.job.errors.join('\n'):'');const next=data?.clientId===selected&&data?.completedAt===s.updatedAt?data:await api('/api/data?id='+selected);if(next?.completedAt!==data?.completedAt||next?.clientId!==data?.clientId){data=next;render()}}catch(e){el('message').textContent=e.message}}
function render(){el('cost-summary').textContent=data?.costSummary?`Себестоимость Ozon заполнена: ${n(data.costSummary.filled)} из ${n(data.costSummary.total)}. Нулевых: ${n(data.costSummary.zero)}; отсутствует: ${n(data.costSummary.missing)}. Получено ${new Date(data.costSummary.importedAt).toLocaleString('ru-RU')}. Это текущие значения, без истории изменений; нулевые значения требуют проверки.`:data?.market==='WB'?'Себестоимость WB не сопоставлена с товарами Ozon.':'';if(!data){el('real-metrics').innerHTML='';el('real-rows').innerHTML='<tr><td colspan="6">Ожидаем первую загрузку.</td></tr>';el('finance-types').innerHTML='';return}const operations=data.operations||[],sum=operations.reduce((s,o)=>s+Number(o.amount||0),0);el('real-metrics').innerHTML=[['Товары',data.sections.products?.ok?n(data.products.length):'Неполные данные'],['Записи остатков',data.sections.stocks?.ok?n(data.stocks.length):'Не загружены'],['Финансовые операции',data.sections.finance?.ok?n(data.operationCount??operations.length):'Неполные данные'],['Начислено по операциям',data.sections.finance?.ok&&data.financeAmountKnown!==false?n(sum)+' ₽':'Расчёт не выполнен']].map(([l,v])=>`<article class="metric"><div class="label">${l}</div><div class="value" style="font-size:22px">${v}</div></article>`).join('');table();const groups={};for(const o of operations){const category=o.operation_type_name||o.operation_type||o.sellerOperName||o.docTypeName;const name=({POSTING:'По отправлениям',ITEM:'По товарам',NON_ITEM:'Без привязки к товару',CONTAINER:'По грузоместам',UNSPECIFIED:'Категория не указана'})[category]||category||'Прочее';groups[name]??={count:0,sum:0};groups[name].count+=o.record_count||1;groups[name].sum+=Number(o.amount||0)}el('finance-types').innerHTML=Object.entries(groups).sort((a,b)=>Math.abs(b[1].sum)-Math.abs(a[1].sum)).map(([k,v])=>`<tr><td>${esc(k)}</td><td>${n(v.count)}</td><td>${data.financeAmountKnown===false?'—':n(v.sum)+' ₽'}</td></tr>`).join('');el('status').textContent+='\nФинансовый период: '+data.period.from+' — '+data.period.to}
function table(){if(!data)return;const q=el('real-search').value.toLowerCase(),items=data.products.filter(p=>(p.name+' '+p.offer_id+' '+p.sku).toLowerCase().includes(q)),stock=new Map(data.stocks.map(p=>[String(p.product_id),p]));el('real-rows').innerHTML=items.slice(0,200).map(p=>{const st=stock.get(String(p.product_id||p.id)),count=st?.stocks?.reduce((s,x)=>s+Number(x.present||0),0);return `<tr><td>${esc(p.name||'Карточка не загружена')}</td><td>${esc(p.offer_id)}</td><td>${esc(p.sku||p.sources?.[0]?.sku||'—')}</td><td>${p.price?n(p.price)+' '+esc(p.currency_code||'RUB'):'—'}</td><td>${p.cost?.status==='filled'?n(p.cost.unitCost)+' '+esc(p.cost.currency||''):p.cost?.status==='zero'?'0 · проверить':'—'}</td><td>${count===undefined?'—':n(count)}</td></tr>`}).join('')||'<tr><td colspan="6">Ничего не найдено</td></tr>';el('real-count').textContent=`Показано ${Math.min(200,items.length)} из ${items.length} найденных. Для остальных уточните поиск. ${data.market==='WB'?'Остатки на складах WB; склады продавца не включены. Цены WB пока не загружены.':'Остаток — сумма present из API, без вычитания резерва.'}`}
el('connect').onsubmit=async e=>{e.preventDefault();const b=el('connect-button');b.disabled=true;el('message').textContent='Проверяем ключ и сохраняем подключение…';try{const r=await api('/api/connect',{name:el('store-name').value,clientId:el('client-id').value.trim(),key:el('api-key').value.trim()});el('api-key').value='';selected=r.id;el('message').textContent='Ключ проверен и сохранён в зашифрованном виде. Начат импорт.';await refresh()}catch(e){el('message').textContent=e.message}finally{b.disabled=false}};el('shops').onclick=e=>{if(e.target.dataset.store){selected=e.target.dataset.store;data=null;refresh()}};el('sync').onclick=async()=>{await api('/api/sync',{id:selected});refresh()};el('real-search').oninput=table;refresh();setInterval(refresh,4000);

el('connect-wb').onsubmit=async e=>{e.preventDefault();el('wb-connect-button').disabled=true;try{const r=await api('/api/connect-wb',{key:el('wb-key').value.trim()});el('wb-key').value='';selected=r.id;data=null;el('message').textContent='WB подключён. Начат импорт.';await refresh()}catch(e){el('message').textContent=e.message}finally{el('wb-connect-button').disabled=false}};
